SELECT * FROM return_request

    user_id = #{userId}

        AND status = #{status}


ORDER BY create_time DESC

mapper.update:
UPDATE return_request
status = #{status}, logistics_company = #{logisticsCompany}, logistics_no = #{logisticsNo}, merchant_remark = #{merchantRemark}, reject_reason = #{rejectReason}, return_address_id = #{returnAddressId}, return_receiver_name = #{returnReceiverName}, return_receiver_phone = #{returnReceiverPhone}, return_address = #{returnAddress}, actual_refund_amount = #{actualRefundAmount}, audit_time = #{auditTime}, receive_time = #{receiveTime}, refund_time = #{refundTime}, update_time = NOW()
WHERE id = #{id}

mapper.select:
SELECT r.id, r.order_id as orderId, r.product_id as productId, r.reason, r.status, r.type, r.refund_amount as refundAmount, r.create_time as createTime, r.merchant_remark as merchantRemark, p.name as productName, p.cover_img as coverImg FROM return_request r LEFT JOIN product p ON r.product_id = p.id WHERE r.merchant_id = #{merchantId}
AND r.status = #{status}
ORDER BY r.create_time DESC

SELECT r.id, r.order_id as orderId, r.order_item_id as orderItemId,
       r.user_id as userId, r.product_id as productId,
       r.reason, r.status, r.type, r.reason_type as reasonType,
       r.refund_amount as refundAmount, r.create_time as createTime,
       o.order_no as orderNo,
       p.name as productName, p.cover_img as coverImg,
       u.username as userName
FROM return_request r
LEFT JOIN `order` o ON r.order_id = o.id
LEFT JOIN product p ON r.product_id = p.id
LEFT JOIN `user` u ON r.user_id = u.id
WHERE r.merchant_id = #{merchantId}

    AND r.status = #{status}


    AND r.type = #{type}


    AND r.create_time >= #{startTime}


    AND r.create_time <= #{endTime}


    AND o.order_no LIKE CONCAT('%', #{orderNo}, '%')


    AND r.user_id = #{userId}


    AND (u.username LIKE CONCAT('%', #{userName}, '%') OR u.nickname LIKE CONCAT('%', #{userName}, '%'))

ORDER BY r.create_time DESC

SELECT reason_type as reasonType, COUNT(*) as totalCount, SUM(CASE WHEN status = 4 THEN 1 ELSE 0 END) as completedCount, SUM(CASE WHEN status IN (0, 1, 2, 3) THEN 1 ELSE 0 END) as approvedCount, SUM(CASE WHEN status = -1 THEN 1 ELSE 0 END) as rejectedCount FROM return_request WHERE merchant_id = #{merchantId}
AND create_time >= #{startTime}
AND create_time <= #{endTime}
GROUP BY reason_type ORDER BY totalCount DESC
